/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Exports the contents of a grid (using the selected order and filters) to a PDF file. &IsAuthorized = SecGAMIsAuthByFunctionalityKey.Udp(!'<Check_Is_Authenticated>') If &IsAuthorized
LoadWWPContext.Call(&WWPContext)
Do 'LoadGridState'
&Title = "Lista de Áreas Ensino e Etapas"
//Report Template Source Header &AppName = "DVelop Software Solutions" &Phone = !"+1 550 8923" &Mail = !"info@mail.com" &Website = !"http://www.web.com" &AddressLine1 = !"French Boulevard 2859" &AddressLine2 = !"Downtown" &AddressLine3 = !"Paris, France" Print printTitle End Footer &PageInfo = "Page: " + &Page.ToString().Trim() &DateInfo = "Date: " + &Today.ToFormattedString() Print printFooter End
Do 'PrintFilters'
Do 'PrintColumnTitles'
Do 'PrintData'
Do 'PrintFooter'
EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
Sub 'PrintFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'AREENSNOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &AreEnsNome1.FromString(&GridStateDynamicFilter.Value) If not &AreEnsNome1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterAreEnsNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilterAreEnsNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterContains") EndCase &AreEnsNome = &AreEnsNome1 print printBlockFilterAreEnsNome EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'AREENSNOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &AreEnsNome2.FromString(&GridStateDynamicFilter.Value) If not &AreEnsNome2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterAreEnsNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilterAreEnsNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterContains") EndCase &AreEnsNome = &AreEnsNome2 print printBlockFilterAreEnsNome EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'AREENSNOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &AreEnsNome3.FromString(&GridStateDynamicFilter.Value) If not &AreEnsNome3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterAreEnsNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilterAreEnsNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterContains") EndCase &AreEnsNome = &AreEnsNome3 print printBlockFilterAreEnsNome EndIf EndCase EndIf EndIf EndIf If not (&TFAreEnsCodigo.IsEmpty() AND &TFAreEnsCodigo_To.IsEmpty()) print printBlockTFAreEnsCodigo &TFAreEnsCodigo_To_Description = format('%1 (%2)', "Código", "WWP_TSTo") print printBlockTFAreEnsCodigo_To EndIf If not &TFAreEnsNome_Sel.IsEmpty() print printBlockTFAreEnsNome_Sel Else If not &TFAreEnsNome.IsEmpty() print printBlockTFAreEnsNome EndIf EndIf If not &TFAreEnsSigla_Sel.IsEmpty() print printBlockTFAreEnsSigla_Sel Else If not &TFAreEnsSigla.IsEmpty() print printBlockTFAreEnsSigla EndIf EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
print printBlockBeforeGrid print printBlockLines_titles
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsAreaEnsino order AreEnsNome when &OrderedBy = 1 AND &OrderedDsc = False order (AreEnsNome) when &OrderedBy = 1 AND &OrderedDsc = True order AreEnsCodigo when &OrderedBy = 2 AND &OrderedDsc = False order (AreEnsCodigo) when &OrderedBy = 2 AND &OrderedDsc = True order AreEnsSigla when &OrderedBy = 3 AND &OrderedDsc = False order (AreEnsSigla) when &OrderedBy = 3 AND &OrderedDsc = True
using trnsAreaEnsinoWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &AreEnsNome1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2 , &AreEnsNome2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3, &AreEnsNome3, &TFAreEnsCodigo , &TFAreEnsCodigo_To, &TFAreEnsNome, &TFAreEnsNome_Sel, &TFAreEnsSigla, &TFAreEnsSigla_Sel) Where prefCodigo = &prefCodigo
Do 'BeforePrintLine' print printBlockLines_data Do 'AfterPrintLine' EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsAreaEnsinoWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsAreaEnsinoWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsAreaEnsinoWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFAREENSCODIGO" &TFAreEnsCodigo.FromString(&GridStateFilterValue.Value) &TFAreEnsCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFAREENSNOME" &TFAreEnsNome.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFAREENSNOME_SEL" &TFAreEnsNome_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFAREENSSIGLA" &TFAreEnsSigla.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFAREENSSIGLA_SEL" &TFAreEnsSigla_Sel.FromString(&GridStateFilterValue.Value) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'BeforePrintLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'AfterPrintLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
